insert into public.docs (col, id, body) values ('krs', 'kr33', '{"unit": "pct", "freq": "weekly", "checkins": [], "close": {"score": "", "worked": "", "noEffect": "", "lessons": "", "next": ""}, "id": "kr33", "obj": "O3", "name": "3.3 · Refunds within 30 days below 3% of Q4 sales", "owner": "romain", "type": "committed", "kind": "ceiling", "metric": "Sales refunded on a request made within 30 days of payment ÷ sales made in the same period (Oct 1 to Dec 31). A ceiling: at or below 3% is on target", "baseline": 3, "target": 3, "current": 3, "expected": 3, "source": "Stripe and the refund backlog, every refund logged with its reason the day it is granted · checked by Romain", "lead": "Share of refunds coming from forced sales", "inits": [{"name": "Forced sales made visible", "hyp": "If we log every refund with its reason and define precisely what a forced sale is, then forced sales become visible, coachable and rare", "contrib": "Refunds from forced sales close to zero"}, {"name": "First 30 days followed up", "hyp": "If the Data OS shows every inactive student and every new student is followed up through their first 30 days, then we catch students at risk before they ask for a refund", "contrib": "Refunds from disengagement"}], "miles": [{"week": 5, "text": "M1 · every refund since Oct 1 logged with its reason in the refund backlog, forced-sale conditions written and validated by the sales team (week to schedule)", "done": false}, {"week": 5, "text": "M2 · Data OS shows every inactive student and every student in their first 30 days, every flagged student contacted within 24 h (week to schedule, shared with KR 1.3 M2)", "done": false}, {"week": 9, "text": "October rate final, below 3%", "done": false}, {"week": 13, "text": "Target · October and November below 3%, December confirmed in January", "done": false}], "risks": [{"text": "Forced sales explain more than half of refunds four weeks after M1", "p": "medium", "i": "medium", "fix": "Sales coaching becomes the first priority, flagged reps’ calls reviewed the following week", "owner": "romain"}, {"text": "A refund request from a student the Data OS never flagged", "p": "medium", "i": "medium", "fix": "Revise the definition of inactive at the next weekly review", "owner": "romain"}, {"text": "A month’s final rate above 3%", "p": "medium", "i": "medium", "fix": "Review its root causes at the next weekly review, before any new sales initiative", "owner": "romain"}]}'::jsonb)
